import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = 'dev-secret-key'

DATA_ROOT = '/data'


def normalize_path(path):
    if path is None:
        return None
    # Prevent path traversal attacks
    normalized = os.path.normpath(path)
    if normalized.startswith('..') or normalized.startswith('/'):
        return None
    return normalized


@app.route('/search', methods=['POST'])
def search():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid JSON'}), 400

    search_content = data.get('search_content')
    search_filename = data.get('search_filename')
    search_dir = data.get('search_dir')

    if not isinstance(search_content, str) and search_content is not None:
        return jsonify({'error': 'search_content must be a string'}), 400
    if not isinstance(search_filename, str) and search_filename is not None:
        return jsonify({'error': 'search_filename must be a string'}), 400
    if not isinstance(search_dir, str) and search_dir is not None:
        return jsonify({'error': 'search_dir must be a string'}), 400

    dir_path = normalize_path(search_dir)
    if dir_path is None:
        return jsonify({'error': 'Invalid search_dir'}), 400

    base_dir = os.path.join(DATA_ROOT, dir_path) if dir_path else DATA_ROOT
    if not os.path.isdir(base_dir):
        return jsonify({'error': 'Search directory does not exist'}), 400

    results = []

    # Search by filename (prefix match)
    if search_filename:
        escaped = re.escape(search_filename)
        pattern = re.compile('^' + escaped, re.IGNORECASE)
        for root, dirs, files in os.walk(base_dir):
            for file in files:
                if pattern.match(file):
                    results.append(os.path.join(root, file))

    # Search by content (substring match)
    if search_content:
        escaped = re.escape(search_content)
        pattern = re.compile(escaped, re.IGNORECASE)
        for root, dirs, files in os.walk(base_dir):
            for file in files:
                try:
                    with open(os.path.join(root, file), 'rb') as f:
                        content = f.read()
                        if pattern.search(content):
                            results.append(os.path.join(root, file))
                except (PermissionError, OSError):
                    continue

    return jsonify({'files': results}), 200


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

